{
  "name": "Filter and sort products",
  "description": "Filters products under 50, sorts them by price, and logs the result.",
  "nodes": [
    {
      "id": "trigger",
      "type": "core.manual_trigger",
      "label": "Paste products",
      "config": {
        "fields": [
          {
            "name": "products",
            "type": "array"
          }
        ]
      }
    },
    {
      "id": "filter_products",
      "type": "transform.filter",
      "label": "Keep under 50",
      "config": {
        "items": "{{trigger.products}}",
        "field": "price",
        "operator": "less_than",
        "value": 50
      }
    },
    {
      "id": "sort_products",
      "type": "transform.sort",
      "label": "Sort by price",
      "config": {
        "items": "{{steps.filter_products.output.items}}",
        "field": "price",
        "direction": "asc"
      }
    },
    {
      "id": "log_result",
      "type": "core.log",
      "label": "Log result",
      "config": {
        "message": "Filtered and sorted products successfully",
        "level": "info"
      }
    }
  ],
  "edges": [
    {
      "source": "trigger",
      "target": "filter_products",
      "sourceHandle": null
    },
    {
      "source": "filter_products",
      "target": "sort_products",
      "sourceHandle": null
    },
    {
      "source": "sort_products",
      "target": "log_result",
      "sourceHandle": null
    }
  ],
  "unsupported": []
}

